<?php
require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../includes/functions.php'; zorunlu_rol('admin','yonetici','hakem');
$id=(int)($_GET['toy_id']??$_POST['toy_id']??0);$toy=null;if($id){$st=$pdo->prepare('SELECT t.*,s.sezon_adi FROM toylar t LEFT JOIN sezonlar s ON s.id=t.sezon_id WHERE t.id=?');$st->execute([$id]);$toy=$st->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!csrf_check($_POST['csrf']??''))throw new RuntimeException('Güvenlik doğrulaması başarısız.');if(!$toy)throw new RuntimeException('Yarışma bulunamadı.');$basliklar=toy_puan_basliklari($toy);$st=$pdo->prepare('SELECT sporcu_id FROM toy_katilimcilari WHERE toy_id=?');$st->execute([$id]);$izinli=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));$gelen=$_POST['puan']??[];$kaydet=$pdo->prepare('INSERT INTO toy_puanlari(toy_id,sporcu_id,puan_anahtari,puan) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE puan=VALUES(puan),updated_at=CURRENT_TIMESTAMP');
  foreach($izinli as $sporcuId)foreach($basliklar as $anahtar=>$_){$deger=str_replace(',','.',trim((string)($gelen[$sporcuId][$anahtar]??'0')));if($deger===''||!is_numeric($deger))$deger=0;if((float)$deger<0)throw new RuntimeException('Puan negatif olamaz.');$kaydet->execute([$id,$sporcuId,$anahtar,$deger]);}
  if(($_POST['tamamla']??'')==='1')$pdo->prepare("UPDATE toylar SET durum='tamamlandi' WHERE id=?")->execute([$id]);else $pdo->prepare("UPDATE toylar SET durum='aktif' WHERE id=?")->execute([$id]);flash_set('basari','Yarışma puanları kaydedildi.');
 }catch(Throwable $e){flash_set('hata',$e->getMessage());}
 redirect(BASE_URL.'/admin/toy-karsilasmalari.php?toy_id='.$id);
}
$turler=toy_turleri();$kategoriler=toy_kategorileri();$liste=$pdo->query("SELECT t.*,s.sezon_adi,COUNT(DISTINCT k.id) katilimci,COALESCE(SUM(p.puan),0) toplam FROM toylar t LEFT JOIN sezonlar s ON s.id=t.sezon_id LEFT JOIN toy_katilimcilari k ON k.toy_id=t.id LEFT JOIN toy_puanlari p ON p.toy_id=t.id GROUP BY t.id ORDER BY t.created_at DESC")->fetchAll();
$sporcular=[];$puanlar=[];$basliklar=[];if($toy){$basliklar=toy_puan_basliklari($toy);$st=$pdo->prepare("SELECT s.id,s.ad,s.soyad,COALESCE(SUM(p.puan),0) toplam FROM toy_katilimcilari k JOIN sporcular s ON s.id=k.sporcu_id LEFT JOIN toy_puanlari p ON p.toy_id=k.toy_id AND p.sporcu_id=s.id WHERE k.toy_id=? GROUP BY s.id ORDER BY toplam DESC,s.ad,s.soyad");$st->execute([$id]);$sporcular=$st->fetchAll();$st=$pdo->prepare('SELECT sporcu_id,puan_anahtari,puan FROM toy_puanlari WHERE toy_id=?');$st->execute([$id]);foreach($st->fetchAll() as $p)$puanlar[(int)$p['sporcu_id']][$p['puan_anahtari']]=$p['puan'];}
ob_start();
?>
<?php if(!$toy): ?><div class="card"><div class="card-head"><h2>Yarışma Puan Girişi</h2><span class="badge">Puan girişi</span></div><p class="muted">Yarışma ve kategoriye göre sporcuların puan giriş ekranını seçin.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Yarışma</th><th>Kategori</th><th>Sporcu</th><th>Toplam Puan</th><th></th></tr></thead><tbody><?php foreach($liste as $x): ?><tr><td><strong><?= e($x['toy_adi']) ?></strong><br><small><?= e($turler[$x['yarisma_turu']]??'') ?></small></td><td><?= e($kategoriler[$x['kategori']]??$x['kategori']) ?></td><td><?= (int)$x['katilimci'] ?></td><td><?= number_format((float)$x['toplam'],2,',','.') ?></td><td><a class="btn btn-sm btn-primary" href="<?= BASE_URL ?>/admin/toy-karsilasmalari.php?toy_id=<?= (int)$x['id'] ?>">Puan Girişi</a></td></tr><?php endforeach; ?><?php if(!$liste): ?><tr><td colspan="5" class="muted">Önce bir yarışma oluşturun.</td></tr><?php endif; ?></tbody></table></div></div>
<?php else: ?><div class="toolbar"><a class="btn btn-outline" href="<?= BASE_URL ?>/admin/toy-karsilasmalari.php">← Yarışma Puan Girişi</a></div><section class="card"><div class="card-head"><h2><?= e($toy['toy_adi']) ?> · <?= e($kategoriler[$toy['kategori']]??$toy['kategori']) ?></h2><span class="badge"><?= e($turler[$toy['yarisma_turu']]??'') ?></span></div><p class="muted">Her puan alanı bağımsız kaydedilir; toplam puan otomatik hesaplanır.</p><form method="post"><input type="hidden" name="toy_id" value="<?= (int)$id ?>"><?= csrf_field() ?><div class="table-wrap"><table class="data-table toy-puan-tablosu"><thead><tr><th>Sporcu</th><?php foreach($basliklar as $etiket): ?><th><?= e($etiket) ?></th><?php endforeach; ?><th>Toplam</th></tr></thead><tbody><?php foreach($sporcular as $sporcu): ?><tr><td><?= e($sporcu['ad'].' '.$sporcu['soyad']) ?></td><?php foreach($basliklar as $anahtar=>$_): ?><td><input type="number" step="0.01" min="0" name="puan[<?= (int)$sporcu['id'] ?>][<?= e($anahtar) ?>]" value="<?= e($puanlar[(int)$sporcu['id']][$anahtar]??0) ?>"></td><?php endforeach; ?><td><strong><?= number_format((float)$sporcu['toplam'],2,',','.') ?></strong></td></tr><?php endforeach; ?><?php if(!$sporcular): ?><tr><td colspan="<?= count($basliklar)+2 ?>" class="muted">Bu yarışma için sporcu bulunmuyor.</td></tr><?php endif; ?></tbody></table></div><div class="form-actions"><button class="btn btn-primary">Puanları Kaydet</button><button class="btn btn-outline" name="tamamla" value="1">Kaydet ve Sonuçları Tamamla</button></div></form></section><?php endif; ?>
<?php $admin_baslik='Yarışma Puan Girişi';$admin_aktif='toy-karsilasmalar';$admin_icerik=ob_get_clean();require __DIR__.'/partials/layout.php';
